import { useEffect, useRef } from "react";

// Vector art lives in flat .svg files under ./vectors, not embedded in TSX.
// Loaded and injected live (not <img src>) because the stylesheet reaches
// INSIDE these — the growth tree's leaves/fruit are targeted by class and
// driven by --uml-progress, and the source marks use currentColor to pick
// up the box label's own ink. Neither works through an opaque <img>.
const cache = new Map<string, Promise<string>>();

function loadSvgText(src: string): Promise<string> {
  let pending = cache.get(src);
  if (!pending) {
    pending = fetch(src).then((res) => {
      if (!res.ok) throw new Error(`InlineSvg: failed to load ${src} (${res.status})`);
      return res.text();
    });
    cache.set(src, pending);
  }
  return pending;
}

export function InlineSvg({
  src,
  as: Tag = "div",
  className,
}: {
  src: string;
  as?: "div" | "span";
  className?: string;
}) {
  const ref = useRef<HTMLDivElement & HTMLSpanElement>(null);

  useEffect(() => {
    let cancelled = false;
    loadSvgText(src).then((svg) => {
      if (!cancelled && ref.current) ref.current.innerHTML = svg;
    });
    return () => {
      cancelled = true;
    };
  }, [src]);

  return <Tag ref={ref} className={className} aria-hidden="true" />;
}
